//! Cargo-driven `shlwapi.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is shlwapi-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x7bc80000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ffab000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ffab000000u64)),
        o => panic!("shlwapi-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:uuid", "engine:wine", "engine:c:cpprt", "import:userenv", "import:oleaut32", "import:ole32", "import:comctl32", "import:comdlg32", "import:mpr", "import:mlang", "import:urlmon", "import:shell32", "import:winmm", "import:version", "import:user32", "import:gdi32", "import:advapi32", "import:wininet", "import:msvcrt", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "engine:oldnames", "import:kernel32_vista", "engine:delayimp_rust"],
        "x86_64" => &["body", "engine:uuid", "engine:wine", "engine:c:cpprt", "import:userenv", "import:oleaut32", "import:ole32", "import:comctl32", "import:comdlg32", "import:mpr", "import:mlang", "import:urlmon", "import:shell32", "import:winmm", "import:version", "import:user32", "import:gdi32", "import:advapi32", "import:wininet", "import:msvcrt", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "engine:oldnames", "import:kernel32_vista", "engine:delayimp_rust"],
        "aarch64" => &["body", "engine:uuid", "engine:wine", "engine:c:cpprt", "import:userenv", "import:oleaut32", "import:ole32", "import:comctl32", "import:comdlg32", "import:mpr", "import:mlang", "import:urlmon", "import:shell32", "import:winmm", "import:version", "import:user32", "import:gdi32", "import:advapi32", "import:wininet", "import:msvcrt", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "engine:oldnames", "import:kernel32_vista", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/shlwapi",
        "dll/win32/shlwapi",
        "sdk/include/wine",
        "sdk/lib/atl",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_SHLWAPI_",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    // cmake built the body with these RUSTFLAGS (its rust_staticlib_variant ENV).
    let body_rustflags = match arch.as_str() {
        "x86" => Some("-C target-feature=+sse,+sse2"),
        _ => None,
    };
    let mut link = Linker::new(target_json);
    if let Some(flags) = body_rustflags {
        link = link.rust_build_rustflags(flags);
    }
    link
        .rust_staticlib("shlwapi-rust")
        .c_from_compile_db("shlwapi_shims", &["dll/win32/shlwapi/policy.cpp", "dll/win32/shlwapi/querysrc.cpp", "dll/win32/shlwapi/propbag.cpp", "dll/win32/shlwapi/utils.cpp", "dll/win32/shlwapi/rust_cohab_stub.c", "dll/win32/shlwapi/rust_varargs_shim.c"])
        .c_from_compile_db("shlwapi_autocomp", &["dll/win32/shlwapi/autocomp.cpp"])
        .rc("dll/win32/shlwapi/shlwapi.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/userenv/userenv.spec", "userenv.dll", "userenv")
        .delay_import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .delay_import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .delay_import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .delay_import_lib("dll/win32/comdlg32/comdlg32.spec", "comdlg32.dll", "comdlg32")
        .delay_import_lib("dll/win32/mpr/mpr.spec", "mpr.dll", "mpr")
        .delay_import_lib("dll/win32/mlang/mlang.spec", "mlang.dll", "mlang")
        .delay_import_lib("dll/win32/urlmon/urlmon.spec", "urlmon.dll", "urlmon")
        .delay_import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .delay_import_lib("dll/win32/winmm/winmm.spec", "winmm.dll", "winmm")
        .delay_import_lib("dll/win32/version/version.spec", "version.dll", "version")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/wininet/wininet.spec", "wininet.dll", "wininet")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
